<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\LoadService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('LOAD_CLARIFICATION_RESPOND_OWN');$id=(int)($_GET['id']??0);$load=LoadService::find($id);if(!$load){http_response_code(404);exit('Load not found.');}if($load['current_status']!=='clarification_required'){http_response_code(409);exit('This load is not awaiting clarification.');}$errors=[];$values=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$load;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{LoadService::respondToClarification($id,$_POST,(int)Auth::user()['id'],(int)$_POST['row_version']);header('Location: '.Url::to('loads/view.php?id='.$id.'&clarified=1'));exit;}catch(RuntimeException $e){$errors[]=$e->getMessage();}catch(Throwable $e){$errors[]='The clarification response could not be saved.';}}$pageTitle='Respond to clarification';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Respond to clarification</h1><p><?=h($load['load_ref'])?> · creates a new immutable load version.</p></div></div><div class="notice"><strong>Operations request:</strong><br><?=nl2br(h($load['clarification_request']??'Please update the load details.'))?></div><?php foreach($errors as $e):?><div class="error"><?=h($e)?></div><?php endforeach;?><form class="card" method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="row_version" value="<?=h($load['row_version'])?>"><?php require BASE_PATH.'/app/Views/loads/form.php';?><div class="field full" style="margin-top:16px"><label>Response note</label><textarea name="clarification_response" rows="4" minlength="5" maxlength="2000" required><?=h($values['clarification_response']??'')?></textarea></div><div class="actions"><button class="button">Submit clarification response</button><a class="button secondary" href="<?=h(Url::to('loads/view.php?id='.$id))?>">Cancel</a></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
